xhtml:div.xhtml:script:
(function(){
  var track = document.getElementById('beltTrack');
  var prevBtn = document.getElementById('prevBtn');
  var nextBtn = document.getElementById('nextBtn');
  var badges = [
    { id:'github-stars', name:'GitHub Stars', tier:'gold', desc:'Repositories that earned 100+ stars.', icon:'<path d="M24 20.694l-2.36-2.17a5 5 0 0 1-3.18-1.42l-2.36 2.17a5 5 0 0 1-3.18 1.42L12 18.54l-4.08 3.64a5 5 0 0 1-6.36 0L2.45 17.43a5 5 0 0 1 0-6.36l2.36-2.17a5 5 0 0 1 3.18-1.42L12 7.07l4.08-3.64a5 5 0 0 1 6.36 0l2.36 2.17a5 5 0 0 1 3.18 1.42l2.36 2.17a5 5 0 0 1 0 6.36l-2.36 2.17a5 5 0 0 1-3.18 1.42zm-4.64-3.64a3 3 0 0 0-1.92 0l-2.36 2.17a3 3 0 0 0 0 3.82l2.36 2.17 4.08-3.64a3 3 0 0 0 0-3.82zm12.96 3.82a3 3 0 0 0 0 3.82l-2.36 2.17a3 3 0 0 0-1.92 0l2.36-2.17a3 3 0 0 0 0-3.82zM12 7.77a3.75 3.75 0 1 1 0 7.5 3.75 3.75 0 0 1 0-7.5z" fill="#ffd700"/>' },
    { id:'year-in-octoverse', name:'Year in the Octoverse', tier:'platinum', desc:'Annual GitHub activity summary badge.', icon:'<path d="M12 2L3 7v9c0 3.31 2.69 6 6 6h6c3.31 0 6-2.69 6-6V7l-9-5zm-1.29 9.41c-.81-.81-2.12-.81-2.93 0l-4.39 4.39a.996.996 0 0 0 0 1.41l4.39 4.39c.39.39 1.02.39 1.41 0l4.39-4.39a.997.997 0 0 0 0-1.41l-4.39-4.39zM12 15l4.39-4.39c.39-.39 1.02-.39 1.41 0s.39 1.02 0 1.41L13.41 15H17v5h-4v-5h1.59z" fill="#8ed1fc"/>' },
    { id:'javascript-expert', name:'JavaScript Expert', tier:'diamond', desc:'Advanced JavaScript programming knowledge.', icon:'<path d="M24 0L4 24v8h20V0zm-4 24h-8v-8l4-4 4 4zm4-16h-8V4h8zm0-8H8l-4 4 4 4z" fill="#f7df1e"/>' },
    { id:'typescript-ninja', name:'TypeScript Ninja', tier:'gold', desc:'Type-safe code across large codebases.', icon:'<path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2zm1.55 11.26h2.9L14.94 15h-0.66l-0.36-1.49h-2.17l-0.36 1.49h-0.66l2.64-7.12h3.12zm-7.27-2.29h2.2l-0.99-2.66h0.77l0.99 2.66h1.6l-1.6-4.31h-2.09zM12 4.93l-2.61 5.29h1.3l0.65-1.39h1.12l0.65 1.39h1.3l-2.61-5.29z" fill="#3178c6"/>' },
    { id:'open-source-contributor', name:'Open Source Contributor', tier:'bronze', desc:'Merged pull requests in 10+ public repositories.', icon:'<path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" fill="#cd7f32"/>' },
    { id:'first-pr', name:'First Pull Request', tier:'bronze', desc:'Opened your first pull request.', icon:'<path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" fill="#cd7f32"/>' },
    { id:'code-reviewer', name:'Code Reviewer', tier:'silver', desc:'Reviewed 50+ pull requests.', icon:'<path d="M19.35 10.04C18.67 6.59 15.64 4 12 4 9.11 4 6.6 5.64 5.35 8.04 5.03 8.55 5 9.24 5 10c0 4.42 4.33 8 9 8s9-3.58 9-8c0-1.13-.01-2.16-.3-2.67-.22-.8-.63-1.67-1.35-2.29zM12 8c-1.1 0-2-.9-2-2s.9-2 2-2 2 .9 2 2-.9 2-2 2zm0 6c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" fill="#c0c0c0"/>' },
    { id:'issue-solver', name:'Issue Solver', tier:'silver', desc:'Closed 25+ issues across repositories.', icon:'<path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-1 16H6v-2.5c0-.3.2-.5.5-.5h1c.3 0 .5.2.5.5v2h12v-2c0-.3.2-.5.5-.5h1c.3 0 .5.2.5.5z" fill="#c0c0c0"/>' },
    { id:'discord-helper', name:'Discord Helper', tier:'platinum', desc:'Helped 100+ developers in community servers.', icon:'<path d="M12 2.5c-5.24 0-9.5 4.26-9.5 9.5S6.76 21.5 12 21.5s9.5-4.26 9.5-9.5S17.24 2.5 12 2.5zm0 17.4c-1.83 0-3.42-.85-4.49-2.19-.2-.24-.3-.52-.3-.82v-1c0-.3.1-.58.3-.82 1.07-1.34 2.66-2.19 4.49-2.19s3.42.85 4.49 2.19l4.39-4.39a.997.997 0 0 0 0-1.41l-4.39-4.39zM12 5c-1.9 0-3.5 1.3-4 3h1c.3 0 .5.2.5.5s-.2.5-.5.5h-1c-.5.8-.8 1.8-.8 2.8 0 1.1.3 2.1.8 2.9V11c0 .3-.1.5-.3.5s-.3-.2-.3-.5c0-1-.2-2-.7-2.8h1c.3 0 .5.2.5.5s-.2.5-.5.5h-1c-.4.7-.6 1.4-.6 2.3 0 1 .3 2.1.8 2.9v1c0 .3-.1.5-.3.5s-.3-.2-.3-.5c0-1.1-.2-2.1-.7-2.9h1c.3 0 .5.2.5.5s-.2.5-.5.5h-1c-.2.2-.3.5-.3.8v1c0 .3-.1.5-.3.5s-.3-.2-.3-.5c0-1-.2-2-.7-2.9h1c.3 0 .5.2.5.5s-.2.5-.5.5h-1c-.5 1-.8 2-.8 3 0 1.2.3 2.2.7 3v1c0 .3-.1.5-.3.5s-.3-.2-.3-.5c0-1-.2-2-.7-3h1c.3 0 .5.2.5.5s-.2.5-.5.5h-1c-.2.2-.3.5-.3.8v1c0 .3-.1.5-.3.5s-.3-.2-.3-.5c0-1-.2-2-.7-2.9h1c.3 0 .5.2.5.5s-.2.5-.5.5z" fill="#5865f2"/>' }
  ];

  function renderBadges(){
    track.innerHTML = badges.map(function(b){
      return '<div class="badge" role="button" tabindex="0" aria-label="'+b.name+': '+b.desc+'">'+
        '<div class="badge-tier tier-'+b.tier+'">'+b.tier+'</div>'+
        '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">'+b.icon+'</svg>'+
        '<div class="badge-name">'+b.name+'</div>'+
      '</div>';
    }).join('');
  }

  function scrollByAmount(px){
    track.scrollBy({ left: px, behavior: 'smooth' });
  }

  function updateButtons(){
    var sl = track.scrollLeft, sw = track.scrollWidth, cw = track.clientWidth;
    prevBtn.disabled = sl <= 2;
    nextBtn.disabled = sl >= sw - cw - 2;
  }

  prevBtn.addEventListener('click', function(){ scrollByAmount(-220); });
  nextBtn.addEventListener('click', function(){ scrollByAmount(220); });
  track.addEventListener('scroll', updateButtons);
  window.addEventListener('resize', updateButtons);

  renderBadges();
  updateButtons();
})();
